-- Bloque · fotos y técnica de cada ejercicio.
-- Fotos: free-exercise-db (dominio público), guardadas en img/ejercicios/.
update public.ejercicios e
set imagenes = v.imagenes, tecnica = v.tecnica
from (values
  ('Encogimientos con mancuernas', array['img/ejercicios/Dumbbell_Shrug/0.webp', 'img/ejercicios/Dumbbell_Shrug/1.webp']::text[], array['Brazos estirados a los costados, mancuernas pegadas al cuerpo.', 'Sube los hombros hacia las orejas, sin doblar los codos.', 'Pausa un segundo arriba y baja lento.']::text[]),
  ('Encogimientos en Multipower', array['img/ejercicios/Barbell_Shrug/0.webp', 'img/ejercicios/Barbell_Shrug/1.webp']::text[], array['Barra a la altura de los muslos, agarre al ancho de hombros.', 'Sube los hombros en línea recta, sin girarlos.', 'Pausa arriba y baja controlado.']::text[]),
  ('Face pull en polea', array['img/ejercicios/Face_Pull/0.webp', 'img/ejercicios/Face_Pull/1.webp']::text[], array['Polea a la altura de la cara, cuerda con las palmas hacia abajo.', 'Tira hacia la frente separando las manos, codos altos.', 'Aprieta las escápulas atrás y vuelve lento.']::text[]),
  ('Pájaros con mancuernas', array['img/ejercicios/Reverse_Flyes/0.webp', 'img/ejercicios/Reverse_Flyes/1.webp']::text[], array['Inclina el torso casi paralelo al piso, espalda recta.', 'Abre los brazos hacia los lados con los codos apenas doblados.', 'Sube hasta la altura de los hombros, sin balancearte.']::text[]),
  ('Remo alto en máquina', array['img/ejercicios/Leverage_High_Row/0.webp', 'img/ejercicios/Leverage_High_Row/1.webp']::text[], array['Pecho apoyado en el respaldo, hombros abajo.', 'Tira de las manijas llevando los codos hacia atrás.', 'Junta las escápulas y vuelve sin soltar de golpe.']::text[]),
  ('Abdominal en máquina', array['img/ejercicios/Ab_Crunch_Machine/0.webp', 'img/ejercicios/Ab_Crunch_Machine/1.webp']::text[], array['Ajusta el asiento para que el pecho quede en la almohadilla.', 'Enrolla el tronco llevando costillas hacia la cadera.', 'Exhala al bajar y vuelve lento; no tires con los brazos.']::text[]),
  ('Crunch en colchoneta', array['img/ejercicios/Crunches/0.webp', 'img/ejercicios/Crunches/1.webp']::text[], array['Rodillas dobladas, pies apoyados, manos junto a la cabeza.', 'Despega solo los hombros del piso, mirando al techo.', 'Sin tirar del cuello; baja controlado.']::text[]),
  ('Plancha', array['img/ejercicios/Plank/0.webp', 'img/ejercicios/Plank/1.webp']::text[], array['Antebrazos bajo los hombros, cuerpo en línea recta.', 'Aprieta glúteos y abdomen: la cadera no se hunde ni sube.', 'Respira normal mientras sostienes.']::text[]),
  ('Plancha lateral', array['img/ejercicios/Side_Bridge/0.webp', 'img/ejercicios/Side_Bridge/1.webp']::text[], array['Codo bajo el hombro, piernas estiradas una sobre otra.', 'Sube la cadera hasta quedar en línea recta.', 'Sostén sin dejar caer la cadera; cambia de lado.']::text[]),
  ('Lumbar en máquina', array['img/ejercicios/Hyperextensions_Back_Extensions/0.webp', 'img/ejercicios/Hyperextensions_Back_Extensions/1.webp']::text[], array['Cadera apoyada en el borde, cuerpo en línea.', 'Baja el tronco controlado, con la espalda recta.', 'Sube hasta quedar alineado; no te arquees de más.']::text[]),
  ('Superman en colchoneta', array['img/ejercicios/Superman/0.webp', 'img/ejercicios/Superman/1.webp']::text[], array['Boca abajo, brazos estirados al frente.', 'Levanta brazos y piernas a la vez unos centímetros.', 'Sostén dos segundos y baja lento.']::text[]),
  ('Pallof press en polea', array['img/ejercicios/Pallof_Press/0.webp', 'img/ejercicios/Pallof_Press/1.webp']::text[], array['De costado a la polea, cable a la altura del pecho.', 'Empuja las manos al frente sin dejar que el tronco gire.', 'Sostén un segundo, vuelve al pecho y cambia de lado.']::text[]),
  ('Rotación de tronco en máquina', array['img/ejercicios/Torso_Rotation/0.webp', 'img/ejercicios/Torso_Rotation/1.webp']::text[], array['Rodillas y cadera fijas en el asiento.', 'Gira el tronco desde el abdomen, sin impulso.', 'Vuelve lento al centro y repite al otro lado.']::text[]),
  ('Equilibrio a una pierna', '{}'::text[], array['De pie sobre una pierna, rodilla apenas flexionada como en postura de derby.', 'Cadera nivelada, abdomen firme, mirada al frente.', 'Para más dificultad, cierra los ojos o usa una superficie inestable.']::text[]),
  ('Bird dog', '{}'::text[], array['En cuatro apoyos, manos bajo hombros y rodillas bajo cadera.', 'Estira un brazo y la pierna contraria hasta quedar en línea.', 'Sostén un segundo sin girar la cadera y cambia de lado.']::text[]),
  ('Curl de muñeca con mancuerna', array['img/ejercicios/Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/0.webp', 'img/ejercicios/Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/1.webp']::text[], array['Antebrazo apoyado en el banco o el muslo, palma hacia arriba.', 'Deja caer la mancuerna hacia los dedos y súbela flexionando la muñeca.', 'Solo se mueve la muñeca; movimiento corto y controlado.']::text[]),
  ('Curl de muñeca con barra', array['img/ejercicios/Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/0.webp', 'img/ejercicios/Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/1.webp']::text[], array['Antebrazos apoyados, palmas hacia arriba, muñecas por fuera del borde.', 'Baja la barra hacia los dedos y súbela con la muñeca.', 'Mantén los antebrazos quietos.']::text[]),
  ('Curl invertido en polea', array['img/ejercicios/Reverse_Cable_Curl/0.webp', 'img/ejercicios/Reverse_Cable_Curl/1.webp']::text[], array['Agarre con las palmas hacia abajo, codos pegados al cuerpo.', 'Sube la barra flexionando los codos sin girar las muñecas.', 'Baja lento; trabaja antebrazo y bíceps.']::text[]),
  ('Curl martillo', array['img/ejercicios/Hammer_Curls/0.webp', 'img/ejercicios/Hammer_Curls/1.webp']::text[], array['Mancuernas con las palmas mirándose, codos pegados.', 'Sube sin girar las muñecas hasta la altura del hombro.', 'Baja controlado, sin balancear el tronco.']::text[]),
  ('Caminata de granjero', array['img/ejercicios/Farmers_Walk/0.webp', 'img/ejercicios/Farmers_Walk/1.webp']::text[], array['Mancuernas pesadas a los costados, hombros atrás.', 'Camina con pasos cortos y el tronco erguido.', 'Aprieta fuerte el agarre todo el recorrido.']::text[]),
  ('Agarre isométrico con discos', array['img/ejercicios/Plate_Pinch/0.webp', 'img/ejercicios/Plate_Pinch/1.webp']::text[], array['Junta dos discos lisos y pellízcalos con los dedos.', 'Sostén con los brazos estirados a los costados.', 'Hombros quietos; aguanta el tiempo indicado.']::text[]),
  ('Press de pecho en máquina', array['img/ejercicios/Leverage_Chest_Press/0.webp', 'img/ejercicios/Leverage_Chest_Press/1.webp']::text[], array['Ajusta el asiento para que las manijas queden a la altura del pecho.', 'Empuja hasta casi estirar los codos, sin bloquearlos.', 'Vuelve lento sin dejar que el peso choque.']::text[]),
  ('Press de banca con mancuernas', array['img/ejercicios/Dumbbell_Bench_Press/0.webp', 'img/ejercicios/Dumbbell_Bench_Press/1.webp']::text[], array['Acostado, pies firmes en el piso, escápulas juntas.', 'Baja las mancuernas a los lados del pecho, codos a unos 45°.', 'Empuja hacia arriba juntándolas un poco al final.']::text[]),
  ('Press de banca en Multipower', array['img/ejercicios/Smith_Machine_Bench_Press/0.webp', 'img/ejercicios/Smith_Machine_Bench_Press/1.webp']::text[], array['La barra debe bajar a la mitad del pecho.', 'Escápulas juntas y pies firmes.', 'Empuja sin despegar los glúteos del banco.']::text[]),
  ('Press inclinado con mancuernas', array['img/ejercicios/Incline_Dumbbell_Press/0.webp', 'img/ejercicios/Incline_Dumbbell_Press/1.webp']::text[], array['Banco a 30–45°, espalda apoyada.', 'Baja las mancuernas a la parte alta del pecho.', 'Empuja hacia arriba sin arquear la espalda.']::text[]),
  ('Press inclinado en Multipower', array['img/ejercicios/Smith_Machine_Incline_Bench_Press/0.webp', 'img/ejercicios/Smith_Machine_Incline_Bench_Press/1.webp']::text[], array['Banco a 30–45°, barra bajando a la parte alta del pecho.', 'Codos un poco por debajo de la barra.', 'Empuja controlado sin rebotar.']::text[]),
  ('Aperturas en pec deck', array['img/ejercicios/Butterfly/0.webp', 'img/ejercicios/Butterfly/1.webp']::text[], array['Espalda apoyada, codos a la altura del pecho.', 'Junta las manijas al frente apretando el pecho.', 'Abre lento hasta sentir el estiramiento, sin pasarte.']::text[]),
  ('Cruce de poleas', array['img/ejercicios/Cable_Crossover/0.webp', 'img/ejercicios/Cable_Crossover/1.webp']::text[], array['Poleas altas, un pie adelante, torso apenas inclinado.', 'Junta las manos al frente con los codos un poco doblados.', 'Vuelve lento manteniendo la tensión.']::text[]),
  ('Press de hombros en máquina', array['img/ejercicios/Leverage_Shoulder_Press/0.webp', 'img/ejercicios/Leverage_Shoulder_Press/1.webp']::text[], array['Asiento ajustado: manijas a la altura de los hombros.', 'Empuja hacia arriba sin bloquear los codos.', 'Baja lento hasta la altura de las orejas.']::text[]),
  ('Press militar con mancuernas', array['img/ejercicios/Dumbbell_Shoulder_Press/0.webp', 'img/ejercicios/Dumbbell_Shoulder_Press/1.webp']::text[], array['Sentado con respaldo, mancuernas a la altura de los hombros.', 'Empuja hacia arriba juntándolas sin chocar.', 'Abdomen firme; no arquees la espalda.']::text[]),
  ('Elevaciones laterales en máquina', array['img/ejercicios/Side_Lateral_Raise/0.webp', 'img/ejercicios/Side_Lateral_Raise/1.webp']::text[], array['Ajusta para que los rodillos queden sobre los codos.', 'Sube los brazos hasta la altura de los hombros.', 'Baja lento; los hombros no se suben hacia las orejas.']::text[]),
  ('Elevaciones laterales con mancuernas', array['img/ejercicios/Side_Lateral_Raise/0.webp', 'img/ejercicios/Side_Lateral_Raise/1.webp']::text[], array['De pie, codos apenas doblados.', 'Sube los brazos hacia los lados hasta la altura de los hombros.', 'Sin balancear; baja en dos o tres segundos.']::text[]),
  ('Extensión de tríceps en polea', array['img/ejercicios/Triceps_Pushdown/0.webp', 'img/ejercicios/Triceps_Pushdown/1.webp']::text[], array['Codos pegados al cuerpo, polea alta.', 'Empuja hacia abajo hasta estirar los brazos.', 'Sube solo hasta 90°, sin despegar los codos.']::text[]),
  ('Extensión de tríceps en máquina', array['img/ejercicios/Machine_Triceps_Extension/0.webp', 'img/ejercicios/Machine_Triceps_Extension/1.webp']::text[], array['Codos apoyados y alineados con el eje de la máquina.', 'Estira los brazos por completo.', 'Vuelve lento sin soltar el peso.']::text[]),
  ('Fondos asistidos', array['img/ejercicios/Dip_Machine/0.webp', 'img/ejercicios/Dip_Machine/1.webp']::text[], array['Más contrapeso = más ayuda.', 'Baja doblando los codos hasta unos 90°, tronco erguido.', 'Empuja hasta estirar sin bloquear.']::text[]),
  ('Prensa de piernas', array['img/ejercicios/Leg_Press/0.webp', 'img/ejercicios/Leg_Press/1.webp']::text[], array['Pies al ancho de la cadera en el centro de la plataforma.', 'Baja hasta que las rodillas formen unos 90°, sin despegar la cadera.', 'Empuja con los talones sin bloquear las rodillas.']::text[]),
  ('Sentadilla en Multipower', array['img/ejercicios/Smith_Machine_Squat/0.webp', 'img/ejercicios/Smith_Machine_Squat/1.webp']::text[], array['Barra sobre los trapecios, pies un poco adelante.', 'Baja como sentándote, rodillas en dirección de los pies.', 'Sube empujando el piso con todo el pie.']::text[]),
  ('Extensión de cuádriceps', array['img/ejercicios/Leg_Extensions/0.webp', 'img/ejercicios/Leg_Extensions/1.webp']::text[], array['Rodilla alineada con el eje de la máquina, rodillo sobre los tobillos.', 'Estira las piernas por completo y aprieta un segundo.', 'Baja lento sin dejar caer el peso.']::text[]),
  ('Sentadilla búlgara con mancuernas', array['img/ejercicios/Split_Squat_with_Dumbbells/0.webp', 'img/ejercicios/Split_Squat_with_Dumbbells/1.webp']::text[], array['Pie de atrás apoyado en un banco, el de adelante lejos.', 'Baja recto hasta que la rodilla de atrás casi toque el piso.', 'Empuja con el talón de adelante; cambia de pierna.']::text[]),
  ('Curl femoral en máquina', array['img/ejercicios/Seated_Leg_Curl/0.webp', 'img/ejercicios/Seated_Leg_Curl/1.webp']::text[], array['Rodilla alineada con el eje, rodillo sobre los tobillos.', 'Dobla las piernas llevando los talones hacia los glúteos.', 'Vuelve lento; la cadera no se levanta.']::text[]),
  ('Peso muerto rumano con mancuernas', array['img/ejercicios/Stiff-Legged_Dumbbell_Deadlift/0.webp', 'img/ejercicios/Stiff-Legged_Dumbbell_Deadlift/1.webp']::text[], array['Rodillas apenas dobladas, espalda recta.', 'Lleva la cadera atrás bajando las mancuernas por delante de las piernas.', 'Baja hasta sentir el estiramiento atrás del muslo y sube apretando glúteos.']::text[]),
  ('Empuje de cadera en máquina', array['img/ejercicios/Barbell_Glute_Bridge/0.webp', 'img/ejercicios/Barbell_Glute_Bridge/1.webp']::text[], array['Espalda alta apoyada, pies al ancho de la cadera.', 'Sube la cadera hasta alinear rodillas, cadera y hombros.', 'Aprieta los glúteos arriba un segundo y baja lento.']::text[]),
  ('Hip thrust con barra', array['img/ejercicios/Barbell_Hip_Thrust/0.webp', 'img/ejercicios/Barbell_Hip_Thrust/1.webp']::text[], array['Espalda alta en el banco, barra sobre la cadera con almohadilla.', 'Empuja con los talones hasta alinear el cuerpo.', 'Mentón hacia el pecho; aprieta glúteos arriba.']::text[]),
  ('Abductores en máquina', array['img/ejercicios/Thigh_Abductor/0.webp', 'img/ejercicios/Thigh_Abductor/1.webp']::text[], array['Espalda apoyada, almohadillas por fuera de las rodillas.', 'Abre las piernas controlado, sin impulso.', 'Vuelve lento; clave para los desplazamientos laterales del derby.']::text[]),
  ('Aductores en máquina', array['img/ejercicios/Thigh_Adductor/0.webp', 'img/ejercicios/Thigh_Adductor/1.webp']::text[], array['Almohadillas por dentro de las rodillas.', 'Junta las piernas apretando la cara interna del muslo.', 'Abre lento hasta un rango cómodo.']::text[]),
  ('Pantorrillas en prensa', array['img/ejercicios/Calf_Press_On_The_Leg_Press_Machine/0.webp', 'img/ejercicios/Calf_Press_On_The_Leg_Press_Machine/1.webp']::text[], array['Solo la punta de los pies en el borde de la plataforma.', 'Empuja estirando los tobillos lo más que puedas.', 'Baja lento hasta sentir el estiramiento.']::text[]),
  ('Jalón al pecho', array['img/ejercicios/Wide-Grip_Lat_Pulldown/0.webp', 'img/ejercicios/Wide-Grip_Lat_Pulldown/1.webp']::text[], array['Agarre un poco más ancho que los hombros, pecho arriba.', 'Tira la barra hacia la parte alta del pecho, codos hacia abajo.', 'Sube lento sin dejar que el peso te levante.']::text[]),
  ('Dominadas asistidas', array['img/ejercicios/Band_Assisted_Pull-Up/0.webp', 'img/ejercicios/Band_Assisted_Pull-Up/1.webp']::text[], array['Más contrapeso = más ayuda.', 'Sube llevando el pecho hacia la barra, codos hacia abajo.', 'Baja controlado hasta estirar los brazos.']::text[]),
  ('Remo sentado en máquina', array['img/ejercicios/Seated_Cable_Rows/0.webp', 'img/ejercicios/Seated_Cable_Rows/1.webp']::text[], array['Pecho apoyado o espalda recta, hombros abajo.', 'Tira llevando los codos atrás, cerca del cuerpo.', 'Junta las escápulas y vuelve lento.']::text[]),
  ('Remo con mancuerna', array['img/ejercicios/One-Arm_Dumbbell_Row/0.webp', 'img/ejercicios/One-Arm_Dumbbell_Row/1.webp']::text[], array['Rodilla y mano del mismo lado apoyadas en el banco, espalda plana.', 'Sube la mancuerna hacia la cadera con el codo pegado.', 'Baja estirando el brazo sin girar el tronco.']::text[]),
  ('Pullover en polea', array['img/ejercicios/Straight-Arm_Pulldown/0.webp', 'img/ejercicios/Straight-Arm_Pulldown/1.webp']::text[], array['Polea alta, brazos estirados, torso apenas inclinado.', 'Baja la barra en arco hasta los muslos sin doblar los codos.', 'Sube lento sintiendo los dorsales.']::text[]),
  ('Curl de bíceps en máquina', array['img/ejercicios/Machine_Bicep_Curl/0.webp', 'img/ejercicios/Machine_Bicep_Curl/1.webp']::text[], array['Brazos apoyados en la almohadilla, codos alineados con el eje.', 'Sube flexionando los codos sin despegarlos.', 'Baja lento hasta casi estirar.']::text[]),
  ('Curl con mancuernas', array['img/ejercicios/Dumbbell_Bicep_Curl/0.webp', 'img/ejercicios/Dumbbell_Bicep_Curl/1.webp']::text[], array['De pie, codos pegados al cuerpo, palmas al frente.', 'Sube sin balancear el tronco.', 'Baja en dos o tres segundos.']::text[])
) as v(nombre, imagenes, tecnica)
where e.nombre = v.nombre;
